const $=s=>document.querySelector(s);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN');
const date=n=>new Date(n*1000).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const icon=(name)=>({bag:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7h14l1 14H4L5 7ZM8 8V6a4 4 0 0 1 8 0v2"/></svg>',search:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/></svg>',user:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/></svg>'}[name]||'↗');
function readCart(){try{const x=JSON.parse(localStorage.getItem('bcc-cart')||'[]');return Array.isArray(x)?x.filter(i=>typeof i.id==='string'&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=10):[];}catch{return [];}}
const state={catalog:[],bundles:[],flags:{ingredient_library:true},user:null,csrf:'',cart:readCart(),theme:new URL(location.href).searchParams.get('theme')||localStorage.getItem('bcc-theme')||'a',account:null,ops:null,filter:'all',otp:null,sessionReady:false};
const format={ 'iron-bisglycinate':'Capsules','l-theanine':'Capsules','vitamin-d3-k2':'Softgels','omega-3-fish-oil':'Softgels','myo-d-chiro-inositol':'Capsules','creatine-chews':'Chewable tablets','psyllium-husk':'Capsules'};
const product=id=>state.catalog.find(p=>p.id===id);
const image=(p,cls='',eager=false)=>`<img class="${cls}" src="/concepts/media/${p.id}.webp" alt="${escape(p.name)} bottle mockup" width="1196" height="1315" ${eager?'fetchpriority="high"':'loading="lazy"'}>`;
async function api(path,data){const res=await fetch('/api'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:data===undefined?undefined:JSON.stringify(data)});const value=await res.json();if(!res.ok)throw new Error(value.error||'Please try again.');return value;}
async function session(){const s=await api('/session');state.user=s.user;state.csrf=s.csrf;state.sessionReady=true;}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4500);}
function saveCart(){localStorage.setItem('bcc-cart',JSON.stringify(state.cart));}
function event(name){let consent=false;try{consent=JSON.parse(localStorage.getItem('bcc-preferences')||'{}').analytics===true;}catch{}if(consent)api('/events',{name}).catch(()=>{});}
function total(){return state.cart.reduce((n,i)=>n+(product(i.id)?.price||0)*i.quantity,0);}
function count(){return state.cart.reduce((n,i)=>n+i.quantity,0);}
function add(id,quantity=1){const p=product(id);if(!p||!p.published||p.stock<1)return toast('This product is unavailable in preview stock.');const existing=state.cart.find(i=>i.id===id);const qty=(existing?.quantity||0)+quantity;if(qty>Math.min(10,p.stock))return toast('The requested quantity exceeds preview availability.');if(existing)existing.quantity=qty;else state.cart.push({id,quantity});saveCart();event('cart_add');renderHeaderCount();toast(`${p.name} added to your preview bag.`);}
function renderHeaderCount(){document.querySelectorAll('[data-cart-count]').forEach(x=>x.textContent=count());}
function badge(text,kind=''){return `<span class="badge ${kind}">${escape(text.replaceAll('_',' '))}</span>`;}
function link(label,url,cls='button'){return `<a class="${cls}" href="${url}">${label}<span>↗</span></a>`;}
function heading(kicker,title,description=''){return `<div class="page-heading"><p class="eyebrow">${kicker}</p><h1>${title}</h1>${description?`<p class="lede">${description}</p>`:''}</div>`;}
function empty(title,text,cta='Explore the collection',href='/shop'){return `<div class="empty"><span class="empty-symbol">✳</span><h2>${title}</h2><p>${text}</p>${link(cta,href)}</div>`;}
function price(p){return `<span class="price">${money(p.price)}</span><span class="sample-price">sample price</span>`;}
function card(p,i=0){return `<article class="product-card" style="--sku:${p.color}"><a class="product-photo" href="/products/${p.id}">${image(p)}<span class="product-index">0${i+1}</span><span class="product-arrow">↗</span></a><div class="product-info"><span class="sku-rule"></span><h3><a href="/products/${p.id}">${escape(p.name)}</a></h3><p>${format[p.id]} · ${escape(p.category)}</p><div class="card-bottom"><div>${price(p)}</div><button class="add-icon" data-add="${p.id}" aria-label="Add ${escape(p.name)} to preview bag" ${!p.stock||!p.published?'disabled':''}>＋</button></div></div></article>`;}
function grid(products=state.catalog){return `<div class="product-grid">${products.map(card).join('')}</div>`;}
function reportTile(){return `<a class="report-tile" href="/reports"><p class="eyebrow">A LITTLE CURIOSITY</p><h3>Start with<br>the details.</h3><p>Have a bottle? Find the report for your lot.</p><span>Find your lot report ↗</span></a>`;}
function shell(content){const mobile=state.user?.mobile;return `<div class="preview-bar"><span>PREVIEW STORE · Sample prices & records. No real payments.</span><div class="theme-switch" role="group" aria-label="Visual direction"><button data-theme-choice="a" aria-pressed="${state.theme==='a'}">A <span>Editorial</span></button><button data-theme-choice="b" aria-pressed="${state.theme==='b'}">B <span>Expressive</span></button></div></div><header class="site-header"><a class="logo" href="/" aria-label="Body Café Co. home"><img src="/assets/brand/logos/Body%20Cafe%20Co%20logo.svg" alt="Body Café Co." width="1080" height="1080"></a><nav class="main-nav" aria-label="Main navigation"><a href="/shop">Shop <span>↗</span></a><a href="/standards">Our Standards</a><a href="/learn">Learn</a><a href="/story">Our Story</a></nav><div class="header-tools"><a class="report-nav" href="/reports">Find your lot report ↗</a><button class="icon-button" data-action="search" aria-label="Search">${icon('search')}</button><a class="icon-button account-icon" href="/account" aria-label="Your account">${icon('user')}</a><a class="bag-link" href="/cart" aria-label="Shopping bag">${icon('bag')}<span data-cart-count>${count()}</span></a><button class="menu-button" data-action="menu" aria-expanded="false" aria-controls="mobile-nav">Menu ＋</button></div></header><nav id="mobile-nav" hidden aria-label="Mobile navigation"><a href="/shop">Shop all seven</a><a href="/bundles">The edits & bundles</a><a href="/standards">Our Standards</a><a href="/learn">Learn</a><a href="/story">Our Story</a><a href="/reports">Find your lot report</a><a href="/account">Your account${mobile?' · '+escape(mobile.slice(-4)):''}</a><a href="/help">Help & support</a></nav><main id="main" tabindex="-1">${content}</main><footer class="site-footer"><div class="footer-brand"><a class="logo" href="/" aria-label="Body Café Co. home"><img src="/assets/brand/logos/Body%20Cafe%20Co%20logo.svg" alt="Body Café Co." width="1080" height="1080"></a><p>Good questions.<br>Clear intentions.</p></div><div><h3>Explore</h3><a href="/shop">All seven essentials</a><a href="/bundles">The edits</a><a href="/standards">Our Standards</a><a href="/learn">Ingredient library</a><a href="/story">Our Story</a></div><div><h3>Here for you</h3><a href="/reports">Find your lot report</a><a href="/help">Help centre</a><a href="/contact">Contact & support</a><a href="/account">Track your order</a><a href="/ops">Operations preview</a></div><div><h3>The small print</h3>${['shipping','returns','cancellation','privacy','terms'].map(x=>`<a href="/policies/${x}">${x[0].toUpperCase()+x.slice(1)}</a>`).join('')}<a href="/settings">Communication preferences</a></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Body Café Co.</span><span>English first. Curious always.</span><span>Draft copy & preview commerce · ${state.theme==='a'?'Warm editorial':'Expressive everyday'}</span></div></footer>`;}

function home(){const d3=product('vitamin-d3-k2'),lt=product('l-theanine');return `<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="sun">✳</span> A LITTLE MORE KNOWING. EVERY DAY.</p><h1>${state.theme==='b'?'Your body.<br>Your curiosity.<br><em>Your café.</em>':'Good things.<br>Clear intentions.<br><em>Your everyday.</em>'}</h1><p>Seven everyday supplements. Clear product details.<br>A place to find the report for your lot.</p><div class="hero-actions">${link('Explore all seven','/shop')}${link('Find your lot report','/reports','text-link')}</div><div class="hero-foot"><span>BODY CAFÉ CO.</span><span>Made for the curious.</span></div></div><div class="hero-art">${image(d3,'hero-primary',true)}<div class="hero-float">${image(lt)}<span>Small habits.<br>Room to grow.</span></div><div class="stamp">A CURIOUS MIND<b>✳</b>A CLEARER CHOICE</div><div class="image-caption"><span>01 / THE EVERYDAY COLLECTION</span><a href="/products/vitamin-d3-k2" aria-label="Explore Vitamin D3 + K2">↗</a></div></div></section><div class="principles"><span>Seven essentials. Your choice.</span><span>Ingredients, explained.</span><span>Lot reports, within reach.</span><span>A little curiosity goes a long way. ✳</span></div><section class="section-wrap"><div class="section-heading"><div><p class="eyebrow">01 — MEET THE COLLECTION</p><h2>${state.theme==='b'?'Seven essentials.<br><em>Which is your thing?</em>':'Find your<br><em>everyday thing.</em>'}</h2></div><p>Different essentials.<br>The same clear approach.</p></div><div class="product-grid">${state.catalog.filter(p=>p.published).map(card).join('')}${reportTile()}</div><div class="section-end">${link('Explore the whole collection','/shop','text-link')}<span>All prices shown are sample values.</span></div></section><section class="split-story section-wrap"><div>${image(product('iron-bisglycinate'))}</div><div class="split-copy"><p class="eyebrow">02 — CLEAR INTENTIONS</p><h2>A good question<br>deserves a<br><em>clear answer.</em></h2><p>What’s inside? How do I use it? Where can I see the report? We’re making room for the questions that matter to you.</p><div class="number-lines"><p><span>01</span><strong>Meet the ingredient.</strong> Understand the form and serving details.</p><p><span>02</span><strong>Read the label.</strong> Find directions and product information.</p><p><span>03</span><strong>Look up your lot.</strong> Follow the details back to your bottle.</p></div>${link('Our approach to clarity','/standards','text-link')}</div></section><section class="formats section-wrap"><p class="eyebrow">03 — FIND YOUR FORMAT</p><div class="section-heading"><h2>Everyday looks<br><em>different on everyone.</em></h2><p>Start with the format.<br>Take time with the details.</p></div><div class="format-grid">${[['Capsules','l-theanine'],['Softgels','omega-3-fish-oil'],['Chewable tablets','creatine-chews']].map(([f,id])=>`<a href="/shop?format=${encodeURIComponent(f)}">${image(product(id))}<span>${f} <b>↗</b></span></a>`).join('')}</div></section><section class="report-banner section-wrap"><div><p class="eyebrow">04 — FROM YOUR BOTTLE TO THE DETAILS</p><h2>Your lot.<br><em>Your closer look.</em></h2><p>The lot number on your pack is where the journey starts.</p>${link('Find your lot report','/reports')}</div><div class="report-illustration"><span>BODY CAFÉ CO. / LOT LOOKUP</span><strong>01 Choose your product</strong><strong>02 Enter your lot number</strong><strong>03 Read the details</strong><p>Explore the sample journey in this preview.</p></div></section><section class="section-wrap"><div class="section-heading"><div><p class="eyebrow">05 — THE EDITS</p><h2>Good together.<br><em>Chosen by you.</em></h2></div>${link('Explore sample bundles','/bundles','text-link')}</div>${bundleGrid()}</section><section class="story-band section-wrap"><p class="eyebrow">A BRAND WITH ROOM FOR QUESTIONS.</p><h2>Curiosity is<br><em>a good place to start.</em></h2><p>Meet the thinking behind Body Café Co.</p>${link('Our Story','/story','text-link')}</section><section class="section-wrap home-help"><div><p class="eyebrow">A LITTLE HELP</p><h2>Before you ask…</h2></div><div>${faqList()}</div></section>`;}
const faqs=[['Where do I find my lot report?','Choose your product on the lot-report page and enter the lot number printed on your pack. This preview includes sample records so you can explore the journey.'],['Can I buy without an account?','The planned experience is guest-first, with mobile-based account access. The preview lets you place an order and later claim matching guest orders using a local preview code.'],['Are these the final prices?','No. All prices and orders in this preview are sample values. Final selling prices, shipping rules and offers await approval.'],['How do returns work?','The working policy includes seven-day unopened returns and issue-based review for opened products. Final timing, shipping responsibility and remedies are still pending.'],['Can I contact someone about a product issue?','Use the support form and choose Product safety for a priority case. The preview stores the case locally and gives you a case ID; it sends no email or WhatsApp message.']];
function faqList(){return faqs.map(([q,a])=>`<details><summary>${q}<span>＋</span></summary><p>${a}</p></details>`).join('');}
function shop(){const q=new URL(location.href).searchParams;const selected=q.get('format')||'all';const category=q.get('category')||'all';const list=state.catalog.filter(p=>p.published&&(selected==='all'||format[p.id]===selected)&&(category==='all'||p.category===category));return `<section class="section-wrap">${heading('THE EVERYDAY COLLECTION','Seven essentials.<br><em>Your kind of everyday.</em>','Take a closer look at the form, the ingredient and the details.')}<div class="shop-tools"><div class="filter-tabs" aria-label="Filter by format">${['all','Capsules','Softgels','Chewable tablets'].map(f=>`<a class="${f===selected?'active':''}" href="/shop${f==='all'?'':'?format='+encodeURIComponent(f)}">${f==='all'?'All seven':f}</a>`).join('')}</div><span>${list.length} product${list.length===1?'':'s'}</span></div>${list.length?grid(list):empty('No match just yet.','Try another format.','Show all products','/shop')}<div class="note-panel">Sample prices throughout this preview. Product claims, full quantities and approved rear-label information will be reviewed before launch.</div></section><section class="mini-banner section-wrap"><h2>Already have a bottle?</h2>${link('Find your lot report','/reports','text-link')}</section>`;}

function detail(p){if(!p)return notFound();event('product_view');return `<section class="section-wrap product-page"><div class="breadcrumbs"><a href="/shop">The collection</a><span>/</span>${escape(p.name)}</div><div class="detail-layout"><div class="detail-gallery">${image(p,'',true)}<div class="gallery-note"><span>01 / SUPPLIED FRONT MOCKUP</span><span>Rear-label view pending</span></div></div><div class="detail-copy"><p class="eyebrow">BODY CAFÉ CO. / ${format[p.id].toUpperCase()}</p><h1>${escape(p.name)}</h1><p class="product-subtitle">${escape(p.subtitle)}</p><div class="detail-price">${price(p)}</div><p class="product-description">Get to know what’s in your bottle. Explore the ingredient, label information and the report for your lot before choosing.</p><div class="fact-lines"><div><span>Format shown</span><strong>${format[p.id]}</strong></div><div><span>Purchase</span><strong>One-time</strong></div><div><span>Serving & pack details</span><strong>Approved data pending</strong></div></div><div class="buy-row"><label for="product-quantity" class="sr-only">Quantity</label><select id="product-quantity">${[1,2,3,4,5].map(n=>`<option value="${n}">${n}</option>`).join('')}</select><button class="button" data-action="add-product" data-id="${p.id}" ${!p.stock||!p.published?'disabled':''}>${p.stock&&p.published?'Add to preview bag':'Unavailable in preview'}<span>＋</span></button></div><p class="micro">Sample purchase only. No real payment or dispatch.</p><form id="pincode-form" class="pincode-form"><label for="pincode">Check delivery</label><div><input id="pincode" name="pincode" inputmode="numeric" pattern="[1-9][0-9]{5}" maxlength="6" placeholder="Six-digit pincode" required><button type="submit">Check ↗</button></div><p id="pincode-result" class="micro" role="status">Explore a sample delivery estimate.</p></form><a class="product-report-link" href="/reports?product=${p.id}"><span>Your lot. Your closer look.</span><strong>Find your lot report ↗</strong></a></div></div></section><section class="section-wrap product-information"><div><p class="eyebrow">THE DETAILS, IN PLAIN SIGHT.</p><h2>A little more<br><em>understanding.</em></h2></div><div><details open><summary>What’s inside <span>＋</span></summary><p>${escape(p.ingredients)}.</p><p>Complete ingredients, actives per serving, allergens and nutrition facts will come from the approved rear label.</p></details><details><summary>How to use <span>＋</span></summary><p>Serving instructions, storage conditions and directions are pending approved label data. This preview does not recommend a dose.</p></details><details><summary>Before you choose <span>＋</span></summary><p>Product-specific cautions, suitability and warnings will be added from reviewed material. No medical diagnosis or personal health recommendation is provided here.</p></details><details><summary>Testing & evidence <span>＋</span></summary><p>Reports must match the product and lot. A test report describes the tested sample; it does not establish authenticity for an individual pack.</p><a class="text-link" href="/reports?product=${p.id}">Explore lot lookup ↗</a></details><details><summary>Delivery & returns <span>＋</span></summary><p>Explore the working shipping and returns policies. Production fees and eligibility rules are not yet final.</p><a class="text-link" href="/policies/returns">Read the policy preview ↗</a></details></div></section><section class="section-wrap reviews-section"><p class="eyebrow">CUSTOMER EXPERIENCES</p><h2>Real people.<br><em>Real experiences.</em></h2><p>Reviews will appear after verified delivery and moderation. We haven’t filled this space with made-up reviews.</p><a href="/account" class="text-link">Have a delivered preview order? Leave a review ↗</a></section><section class="section-wrap related"><div class="section-heading"><h2>More to<br><em>get to know.</em></h2><p>Explore the collection.<br>Choose each product on its own merits.</p></div>${grid(state.catalog.filter(x=>x.published&&x.id!==p.id).slice(0,3))}</section>`;}
function bundleGrid(){return `<div class="bundle-grid">${state.bundles.map(b=>{const items=b.items.map(product);return `<article class="bundle-card"><a class="bundle-images" href="/bundles/${b.id}">${items.map(p=>image(p)).join('')}</a><div><p class="eyebrow">ILLUSTRATIVE COLLECTION · NOT AN APPROVED OFFER</p><h3>${b.name}</h3><p>${b.description}</p><span>${money(items.reduce((n,p)=>n+p.price,0))} <small>sample item total · no bundle discount</small></span>${link('Explore this edit','/bundles/'+b.id,'text-link')}</div></article>`;}).join('')}</div>`;}
function bundles(id){const b=state.bundles.find(b=>b.id===id);if(id&&!b)return notFound();return `<section class="section-wrap">${heading('THE EDITS',b?b.name:'A little collection.<br><em>All your own.</em>',b?b.description:'Explore sample combinations. Final bundles and any savings require approval.')} ${b?`<div class="bundle-detail"><div class="bundle-images">${b.items.map(id=>image(product(id))).join('')}</div><div><p class="eyebrow">SAMPLE COMBINATION</p><h2>What’s in<br><em>this edit.</em></h2>${b.items.map(id=>{const p=product(id);return `<div class="bundle-line"><a href="/products/${id}">${p.name} ↗</a><span>${money(p.price)}</span></div>`;}).join('')}<div class="bundle-line total"><strong>Sample item total</strong><strong>${money(b.items.reduce((n,id)=>n+product(id).price,0))}</strong></div><p class="micro">No discount claimed. Component stock is checked individually. This is not a recommendation to take these products together.</p><button class="button full" data-bundle="${b.id}">Add both to preview bag <span>＋</span></button></div></div>`:bundleGrid()}</section>`;}

function standards(){return `<section class="section-wrap">${heading('OUR STANDARDS','Good questions.<br><em>Clear intentions.</em>','Clarity begins with being specific about what we know, what we show and what a report can tell you.')}<div class="standards-intro"><div>${image(product('omega-3-fish-oil'))}</div><div><h2>The detail<br>behind the bottle.</h2><p>Ingredients and reports deserve more than a small badge. Our planned approach connects the product, its approved label, and the evidence for its manufacturing lot.</p><a href="/reports" class="text-link">Explore the lot-report experience ↗</a></div></div><div class="editorial-steps">${[['01','The product','An approved product record identifies the formulation, directions, claims and label.'],['02','The manufacturing lot','The lot record connects the product to manufacturing details and approved evidence.'],['03','The public report','A readable summary and approved source files help you inspect what was tested.'],['04','The limit of the evidence','A lot report is not a diagnosis, a promise of individual results or proof of authenticity for every unit.']].map(([n,t,d])=>`<div><span>${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="note-panel"><strong>Where we are today</strong><p>This preview uses illustrative lot records. Laboratory reports, certifications and finished-product clinical claims have not been supplied or asserted.</p></div></section><section class="report-banner section-wrap"><h2>See the details.<br><em>Ask the questions.</em></h2>${link('Find your lot report','/reports')}</section>`;}
const learning=[['reading-a-label','Read a label with confidence.','A practical guide to ingredient names, serving sizes and the details on your pack.'],['understanding-reports','What does a lot report show?','Understand the difference between a product, a manufacturing lot and a tested sample.'],['ingredient-forms','Get to know ingredient forms.','Why the full ingredient name matters when you compare products.']];
function learn(slug){const item=learning.find(x=>x[0]===slug);const p=product(slug);if(slug&&!item&&!p)return notFound();if(item)return `<article class="section-wrap article">${heading('THE CLARITY LIBRARY',item[1],item[2])}<p class="article-meta">Body Café Co. · General product-literacy guide</p>${slug==='reading-a-label'?`<h2>Start with the serving.</h2><p>The amount per serving and the number of units in that serving are different pieces of information. Read them together before comparing products.</p><h2>Read the full ingredient list.</h2><p>The headline ingredient does not describe the whole formulation. Look for the complete list, allergens, directions, warnings, storage and manufacturer details.</p><h2>Keep the lot number.</h2><p>Your pack’s lot number connects it to manufacturing records. It is different from a barcode, SKU or order number.</p>`:slug==='understanding-reports'?`<h2>A product is not a lot.</h2><p>A product can have multiple manufacturing lots. A report should identify the sample and lot it describes.</p><h2>Look at what was tested.</h2><p>Read the test parameter, result, units, method and any stated limits together. A result should not be presented as a pass without an applicable reviewed specification.</p><h2>Know what it cannot prove.</h2><p>A laboratory result does not promise an individual health outcome or verify the authenticity of every pack. Our production summaries and files will require review before publication.</p>`:`<h2>The full name matters.</h2><p>An ingredient’s form is part of its identity. Keep the form visible alongside the quantity and serving information rather than reducing everything to a short marketing name.</p><h2>Compare like with like.</h2><p>For a formulation containing multiple ingredients, compare each declared component. Our final product pages will use the approved quantities and wording from their labels.</p>`}${link('Back to the library','/learn','text-link')}</article>`;if(p)return `<section class="section-wrap article">${heading('INGREDIENT NOTES',escape(p.name),escape(p.subtitle))}<div class="ingredient-inline">${image(p)}<div><h2>What’s in view.</h2><p>${escape(p.ingredients)}.</p><p>Amounts, ingredient sources, approved uses and supporting references await the reviewed product record. This page does not turn a name into a health claim.</p>${link('Explore the product','/products/'+p.id)}</div></div>${link('Back to the library','/learn','text-link')}</section>`;return `<section class="section-wrap">${heading('THE CLARITY LIBRARY','A little learning.<br><em>A clearer choice.</em>','Start with the label. Get to know the ingredient. Understand what the report can show.')}<div class="learning-grid">${learning.map((a,i)=>`<a class="learning-card" href="/learn/${a[0]}"><span>0${i+1} / THE GUIDES</span><h2>${a[1]}</h2><p>${a[2]}</p><b>Read the guide ↗</b></a>`).join('')}</div><div class="section-heading below"><h2>Meet the ingredients.</h2><p>Product-specific notes await approved specifications.</p></div><div class="ingredient-list">${state.catalog.map(p=>`<a href="/learn/${p.id}"><span style="background:${p.color}"></span><strong>${p.name}</strong><span>Explore ↗</span></a>`).join('')}</div></section>`;}
function story(){return `<section class="section-wrap story-page">${heading('OUR STORY','Curiosity is<br><em>a good place to start.</em>','Body Café Co. is taking shape around a simple idea: the details should be easier to find.')}<div class="story-composition">${image(product('psyllium-husk'))}${image(product('l-theanine'))}<div><span>BODY CAFÉ CO.</span><h2>Good questions.<br>Every day.</h2></div></div><div class="story-text"><p class="eyebrow">THE THINKING BEHIND THE BRAND</p><h2>Make room<br>for understanding.</h2><p>A product name is a starting point. We want the ingredients, label information and lot records to help you take the next step with clarity.</p><p>The founder’s personal story, team details and original photography will be added in their own words. This draft does not invent a founding history, credentials or expert endorsements.</p>${link('Explore our approach','/standards','text-link')}</div></section>`;}

function reports(){const pid=new URL(location.href).searchParams.get('product')||'vitamin-d3-k2';const index=Math.max(0,state.catalog.findIndex(p=>p.id===pid));return `<section class="section-wrap report-page">${heading('FROM YOUR BOTTLE TO THE DETAILS','Your lot.<br><em>Your closer look.</em>','Choose your product, then enter the lot number printed on your pack.')}<div class="report-layout"><div><div class="report-product-picker">${state.catalog.map(p=>`<button class="${p.id===pid?'selected':''}" data-report-product="${p.id}" aria-label="Choose ${p.name}" aria-pressed="${p.id===pid}">${image(p)}<span>${p.name}</span></button>`).join('')}</div><details class="lot-guide"><summary>Where is my lot number? <span>＋</span></summary><p>The location guide will be added from the final rear label. A lot number is different from your order number or product barcode.</p></details></div><form id="report-form" class="form-panel"><p class="eyebrow">FIND YOUR LOT REPORT ↗</p><label for="report-product">Your product</label><select id="report-product" name="product">${state.catalog.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${p.name}</option>`).join('')}</select><label for="lot">Lot number</label><input id="lot" name="lot" placeholder="e.g. DEMO-${String(index+1).padStart(2,'0')}-01" maxlength="60" required><p class="micro">For a sample match, try <strong id="sample-lot">DEMO-${String(index+1).padStart(2,'0')}-01</strong>.</p><button class="button full" type="submit">Look up sample record <span>↗</span></button><details class="sample-states"><summary>Explore other sample states <span>＋</span></summary><div class="sample-buttons">${['UNKNOWN','DEMO-UNPUBLISHED','DEMO-WITHDRAWN','DEMO-OUTAGE'].map(s=>`<button type="button" data-sample-lot="${s}">${s.replace('DEMO-','').toLowerCase()}</button>`).join('')}</div></details><p class="micro">Preview records only. A lot report does not authenticate an individual pack.</p><div id="report-result" role="status" aria-live="polite"></div></form></div></section>`;}

function cart(){return `<section class="section-wrap">${heading('YOUR BAG','A little collection.<br><em>All your own.</em>')}${state.cart.length?`<div class="cart-layout"><div>${state.cart.map(i=>{const p=product(i.id);if(!p)return '';return `<article class="cart-line"><a href="/products/${p.id}">${image(p)}</a><div><h2><a href="/products/${p.id}">${p.name}</a></h2><p>${format[p.id]} · sample price ${money(p.price)}</p><div class="quantity-control"><button data-quantity="${p.id}" data-change="-1" aria-label="Decrease ${p.name} quantity">−</button><span>${i.quantity}</span><button data-quantity="${p.id}" data-change="1" aria-label="Increase ${p.name} quantity">＋</button></div><button class="remove" data-remove="${p.id}">Remove</button></div><strong>${money(p.price*i.quantity)}</strong></article>`;}).join('')}<a class="text-link" href="/shop">← Keep exploring</a></div><aside class="order-summary"><p class="eyebrow">YOUR PREVIEW ORDER</p><div><span>Sample subtotal</span><strong>${money(total())}</strong></div><div><span>Delivery</span><span>Calculated at checkout</span></div><p>One-time purchases. Final prices, tax and shipping rules await approval.</p>${link('Continue to preview checkout','/checkout','button full')}<span class="micro">No money will be collected.</span></aside></div>`:empty('A little room for possibility.','Your bag is empty. Get to know the seven essentials.')}</section>`;}
function addressFields(prefix='',v={}){return `<div class="field-grid">${[['name','Full name','text'],['mobile','Mobile number','tel'],['email','Email (optional)','email'],['pincode','Pincode','text'],['address','Address','text'],['city','City','text'],['state','State','text']].filter(([k])=>prefix!=='saved-'||!['mobile','email'].includes(k)).map(([k,l,t])=>`<div class="field ${k==='address'?'span-two':''}"><label for="${prefix+k}">${l}</label><input id="${prefix+k}" name="${k}" type="${t}" value="${escape(v[k]||'')}" ${k==='email'?'':'required'} ${k==='mobile'?'inputmode="tel" pattern="[6-9][0-9]{9}" maxlength="10"':k==='pincode'?'inputmode="numeric" pattern="[1-9][0-9]{5}" maxlength="6"':'maxlength="200"'}></div>`).join('')}</div>`;}
function checkout(){if(!state.cart.length)return `<section class="section-wrap">${empty('Your bag is empty.','Add an essential before starting checkout.')}</section>`;event('checkout_start');return `<section class="section-wrap">${heading('GUEST-FIRST CHECKOUT','Good choices.<br><em>Clear next steps.</em>','This is a preview checkout. Use sample contact details; no payment or messages will be sent.')}<div class="checkout-layout"><form id="checkout-form" class="checkout-form"><div class="form-section"><p class="eyebrow">01 / DELIVERY DETAILS</p>${addressFields('',{mobile:state.user?.mobile||''})}<details><summary>Need a GST invoice? <span>＋</span></summary><label for="gstin">GSTIN (optional)</label><input id="gstin" name="gstin" maxlength="15"><label for="legal-name">Legal name</label><input id="legal-name" name="legal_name" maxlength="200"></details></div><div class="form-section"><p class="eyebrow">02 / PAYMENT</p><label class="payment-choice"><input type="radio" checked name="method" value="prepaid"><span><strong>Prepaid · preview payment</strong><small>UPI, cards, wallets and net banking are planned with Razorpay.</small></span></label><div class="disabled-option"><span>Cash on delivery</span>${badge('Policy pending')}<p>The ₹150 collection method and courier COD charge need confirmation before activation.</p></div></div><div class="form-section"><p class="eyebrow">03 / YOUR CHOICE</p><label class="check"><input type="checkbox" name="adult" required><span>I confirm the purchaser is 18 or older.</span></label><label class="check"><input type="checkbox" name="email_consent"><span>I’d like optional email updates. (Optional)</span></label><label class="check"><input type="checkbox" name="whatsapp_consent"><span>I’d like optional WhatsApp updates. (Optional)</span></label><p class="micro">Marketing choices are separate and unchecked. See <a href="/policies/privacy">privacy</a> and the <a href="/policies/terms">working terms</a>.</p><div class="form-error" role="alert"></div><button class="button full" type="submit">Create preview order <span>↗</span></button><p class="micro">A 15-minute preview stock reservation starts when this order is created.</p></div></form><aside class="order-summary checkout-summary"><p class="eyebrow">YOUR BAG / ${count()} ITEMS</p>${state.cart.map(i=>{const p=product(i.id);return `<div class="summary-product">${image(p)}<span>${p.name}<small>Qty ${i.quantity}</small></span><strong>${money(p.price*i.quantity)}</strong></div>`;}).join('')}<label for="discount-code">Sample discount code</label><div class="discount-input"><input id="discount-code" form="checkout-form" name="discount" placeholder="Try PREVIEW10"><button type="button" data-action="discount">Apply</button></div><div><span>Subtotal</span><strong>${money(total())}</strong></div><div><span>Discount</span><strong id="checkout-discount">—</strong></div><div><span>Sample delivery</span><strong id="checkout-shipping">${total()>=1499?'Free':money(75)}</strong></div><div class="summary-total"><span>Sample total</span><strong id="checkout-total">${money(total()+(total()>=1499?0:75))}</strong></div><p class="micro">Sample pricing only; no final GST calculation is asserted.</p></aside></div></section>`;}

function loginPanel(){return `<div class="account-welcome"><div><p class="eyebrow">YOUR EVERYDAY, IN ONE PLACE</p><h2>A little more<br><em>connected.</em></h2><p>Track your orders, keep your addresses and pick up where you left off.</p></div><form id="otp-form" class="form-panel"><p class="eyebrow">MOBILE SIGN-IN / PREVIEW</p><label for="login-mobile">Mobile number</label><input id="login-mobile" name="mobile" inputmode="tel" pattern="[6-9][0-9]{9}" maxlength="10" placeholder="10-digit Indian number" required><button class="button full" type="submit">Get preview code <span>→</span></button><p class="micro">A local code will appear here. No SMS is sent. Real OTP and email fallback require provider setup.</p><div id="otp-result" role="status"></div><div class="form-error" role="alert"></div></form></div>`;}
function accountNav(tab='orders'){return `<nav class="account-tabs" aria-label="Account sections">${[['orders','Orders','/account'],['addresses','Addresses','/account/addresses'],['cases','Support cases','/account/cases'],['preferences','Preferences','/settings']].map(([id,l,u])=>`<a class="${id===tab?'active':''}" href="${u}">${l}</a>`).join('')}<button data-action="logout">Sign out</button></nav>`;}
function orderCard(o){return `<article class="order-card"><div class="order-card-top"><div><span class="eyebrow">${o.id}</span><p>${date(o.created)}</p></div>${badge(o.state)}</div><div class="order-thumbnails">${o.items.map(i=>image(product(i.id))).join('')}</div><div class="order-card-bottom"><span>${o.items.reduce((n,i)=>n+i.quantity,0)} items · ${money(o.total)} sample</span>${link('View order','/orders/'+o.id,'text-link')}</div></article>`;}
function account(tab){const a=state.account;const guest=state.user.id.startsWith('guest-');return `<section class="section-wrap">${heading('YOUR ACCOUNT','Your everyday.<br><em>All together.</em>',guest?'Sign in to claim matching guest orders, or review orders from this preview session.':`Signed in with mobile ending ${escape(state.user.mobile.slice(-4))}.`)}${guest?loginPanel():''}${accountNav(tab)}${tab==='addresses'?`<div class="account-columns"><div><h2>Saved addresses.</h2>${a.addresses.length?a.addresses.map(v=>`<article class="address-card"><strong>${escape(v.name)}</strong><p>${escape(v.address)}<br>${escape(v.city)}, ${escape(v.state)} ${escape(v.pincode)}</p></article>`).join(''):'<p>No saved addresses yet.</p>'}</div><form id="address-form" class="form-panel"><p class="eyebrow">ADD A PREVIEW ADDRESS</p>${addressFields('saved-')}<div class="form-error" role="alert"></div><button class="button full">Save address <span>＋</span></button></form></div>`:tab==='cases'?`<div class="section-heading"><h2>Your conversations.</h2>${link('Open a support case','/contact','text-link')}</div>${a.cases.length?`<div class="case-grid">${a.cases.map(caseCard).join('')}</div>`:empty('Nothing to follow up on.','Your support case IDs and updates will appear here.','Contact support','/contact')}`:a.orders.length?`<div class="orders-grid">${a.orders.map(orderCard).join('')}</div>`:empty('Your first chapter starts here.','Preview orders from this session will appear in your account.')}</section>`;}
function caseCard(c){return `<article class="case-card"><div>${badge(c.kind,c.kind==='safety'?'warning':'')}${badge(c.state)}</div><h3>${c.id}</h3><p>${escape(c.message)}</p><small>${escape(c.owner)} · ${escape(c.sla)}</small>${c.order_id?`<a class="text-link" href="/orders/${c.order_id}">${c.order_id} ↗</a>`:''}</article>`;}
function payment(o){if(!o)return notFound();const expired=o.state==='expired'||o.expires<Date.now()/1000;return `<section class="section-wrap payment-page">${heading('PREVIEW PAYMENT',o.state==='paid'?'A little confirmation.<br><em>All in order.</em>':'Your order.<br><em>One clear next step.</em>',`${o.id} · No real payment is processed.`)}<div class="payment-layout"><div class="form-panel"><p class="eyebrow">LOCAL PAYMENT SIMULATOR</p><h2>${money(o.total)}</h2><p class="micro">Sample order total</p>${o.state==='paid'?`${badge('Preview payment captured')}<p>No money moved. Your preview order is ready to explore.</p>${link('View your order','/orders/'+o.id)}`:o.state!=='pending'?`${badge(o.state)}<p>This order no longer has an active payment step.</p>${link('View your order','/orders/'+o.id)}`:expired?`<p>This reservation has expired. Start a new checkout to check availability again.</p>${link('Return to bag','/cart')}`:`<p>Try a success or failure to see the order journey. Inventory is reserved for 15 minutes.</p><p class="reservation-time" data-expires="${o.expires}"></p><button class="button full" data-pay="success" data-id="${o.id}">Simulate successful payment <span>→</span></button><button class="button outline full" data-pay="failure" data-id="${o.id}">Simulate failed payment <span>↻</span></button><p id="payment-result" role="status"></p>`}</div><div class="order-summary"><p class="eyebrow">YOUR PREVIEW RECORD</p>${o.items.map(i=>`<div><span>${escape(i.name)} × ${i.quantity}</span><strong>${money(i.unit_price*i.quantity)}</strong></div>`).join('')}<div><span>Sample discount</span><span>−${money(o.discount)}</span></div><div><span>Sample shipping</span><span>${money(o.shipping)}</span></div><div class="summary-total"><span>Total</span><strong>${money(o.total)}</strong></div><p>Final Razorpay integration needs server credentials, signature verification, webhook reconciliation and settlement testing.</p></div></div></section>`;}
function orderDetail(o){if(!o)return `<section class="section-wrap">${empty('Order not found.','Sign in to the customer session that owns this order.','Your account','/account')}</section>`;const customer=state.user.role==='customer';const canCancel=customer&&['pending','paid'].includes(o.state);return `<section class="section-wrap">${heading('YOUR ORDER',o.id,`Created ${date(o.created)} · Preview transaction only.`)}<div class="order-detail-layout"><div><div class="tracking-card"><div class="section-heading"><h2>${o.state==='delivered'?'At your door.':o.state==='shipped'?'On its way.':o.state==='paid'?'We have your order.':'Your order status.'}</h2>${badge(o.state)}</div><div class="timeline">${['pending','paid','shipped','delivered'].map((s,i)=>{const occurred=o.history.find(h=>h.state===s);return `<div class="${occurred?'done':''}"><span>${occurred?'✓':i+1}</span><strong>${s==='pending'?'Order created':s==='paid'?'Preview paid':s==='shipped'?'Shipped':'Delivered'}</strong><small>${occurred?date(occurred.at):'Not yet'}</small></div>`;}).join('')}</div>${o.provider?`<p>${escape(o.provider)} · ${escape(o.tracking)} <small>Simulated tracking; no shipment booked.</small></p>`:''}${o.refund!=='none'?`<p>Refund: ${badge(o.refund)}</p>`:''}</div><div class="order-items">${o.items.map(i=>`<div>${image(product(i.id))}<span><strong>${i.name}</strong><small>Quantity ${i.quantity}</small></span><strong>${money(i.quantity*i.unit_price)}</strong></div>`).join('')}</div><div class="order-actions">${o.state==='pending'?link('Continue preview payment','/payment/'+o.id):''}${canCancel?`<button class="button outline" data-cancel="${o.id}">Cancel preview order</button>`:''}<button class="button outline" data-reorder="${o.id}">Reorder items ＋</button>${link('Get help with this order','/contact?order='+o.id,'text-link')}</div>${customer&&o.state==='delivered'?`<form id="review-form" class="form-panel"><p class="eyebrow">VERIFIED PREVIEW DELIVERY</p><h2>How was your experience?</h2><input type="hidden" name="order_id" value="${o.id}"><label for="review-product">Product</label><select id="review-product" name="product">${o.items.map(i=>`<option value="${i.id}">${i.name}</option>`).join('')}</select><label for="rating">Rating</label><select id="rating" name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} stars</option>`).join('')}</select><label for="review-text">Your review</label><textarea id="review-text" name="text" minlength="10" maxlength="1000" required></textarea><div class="form-error" role="alert"></div><button class="button">Submit for preview moderation ↗</button></form>`:''}</div><aside class="order-summary"><p class="eyebrow">ORDER SUMMARY</p><div><span>Sample subtotal</span><span>${money(o.subtotal)}</span></div><div><span>Sample discount</span><span>−${money(o.discount)}</span></div><div><span>Sample delivery</span><span>${money(o.shipping)}</span></div><div class="summary-total"><strong>Total</strong><strong>${money(o.total)}</strong></div><h3>Delivery address</h3><p>${escape(o.contact.name)}<br>${escape(o.contact.address)}<br>${escape(o.contact.city)}, ${escape(o.contact.state)}<br>${escape(o.contact.pincode)}</p><p class="micro">Policy snapshot: ${o.policy_version}</p></aside></div></section>`;}

function help(){return `<section class="section-wrap">${heading('A LITTLE HELP','Good questions.<br><em>We’re here for them.</em>','Start with an answer, or open a case to keep the conversation together.')}<div class="help-links">${[['Orders & delivery','Follow your preview order.','/account'],['Returns & replacements','Understand the working policy.','/policies/returns'],['Product & lot reports','Explore the details for your pack.','/reports'],['Something else?','Open a support case.','/contact']].map(([t,d,u])=>`<a href="${u}"><h2>${t}</h2><p>${d}</p><span>↗</span></a>`).join('')}</div><div class="faq-section">${faqList()}</div></section>`;}
function contact(){const oid=new URL(location.href).searchParams.get('order')||'';return `<section class="section-wrap">${heading('LET’S KEEP THE CONVERSATION TOGETHER','A question?<br><em>Start here.</em>','Every preview case gets an ID and stays in your account. No external messages are sent.')}<div class="contact-layout"><div><h2>A little human help.</h2><p>WhatsApp, email, web and phone are planned support channels. Confirmed contact details and service hours will appear before launch.</p><div class="contact-channel"><strong>WhatsApp</strong><span>Business number pending</span></div><div class="contact-channel"><strong>Email</strong><span>Support address pending</span></div><div class="contact-channel"><strong>Phone</strong><span>Initial service planned</span></div><div class="note-panel"><strong>Product issue?</strong><p>Choose Product safety for a dedicated priority case. In this preview the case is local; no safety outreach or recall is initiated automatically.</p></div></div><form id="case-form" class="form-panel"><p class="eyebrow">OPEN A PREVIEW CASE</p><label for="case-kind">What can we help with?</label><select id="case-kind" name="kind"><option value="general">General question</option><option value="delivery">Delivery</option><option value="return">Unopened return</option><option value="replacement">Replacement / product issue</option><option value="safety">Product safety</option></select><label for="case-order">Order ID (optional)</label><input id="case-order" name="order_id" value="${escape(oid)}" maxlength="40"><label for="case-message">Tell us a little more</label><textarea id="case-message" name="message" minlength="10" maxlength="3000" required placeholder="Describe the issue and the relevant product or lot."></textarea><p class="micro">Do not include medical records or payment credentials in the preview.</p><div class="form-error" role="alert"></div><button class="button full">Create preview case <span>↗</span></button><div id="case-result" role="status"></div></form></div></section>`;}
const policies={shipping:['Shipping & delivery','One active D2C warehouse is planned, with Vayuvega and Shipneer as the named providers.','The preview uses an illustrative ₹75 delivery charge, waived on a sample subtotal after discount of ₹1,499 or more. This is not the approved shipping policy.','Pincode estimates are illustrative. Production serviceability and delivery dates require courier configuration.'],returns:['Returns & refunds','The working direction includes seven-day returns for unopened items and issue-based review for opened products.','The start of that window, shipping responsibility, replacement rules and the proposed longer issue-reporting exception await confirmation.','Use support to open a return or replacement case. Preview refunds are accounting demonstrations and do not move money.'],cancellation:['Cancellation','The working direction allows cancellation before shipment initiation.','The local preview permits cancellation while an order is pending or paid. Once marked shipped, a support case is required.','Paid cancellation restores preview inventory and marks a refund pending. An Admin initiates the refund approval and a different Admin must approve it.'],privacy:['Privacy & your choices','This local preview stores session, order, address and support data in a local SQLite database. No marketing provider receives this data.','Email and WhatsApp marketing choices are separate and unchecked by default. The production retention schedule, contact details and final privacy notice need approval.','Use sample data while reviewing. Local demo sign-in is not production authentication.'],terms:['Terms of the preview','This website is a local functional preview, not a live offer for sale. All prices, stock, reports and transactions are illustrative.','No real payments are accepted, shipments booked, laboratory reports issued or external messages sent.','Final terms of sale, business disclosures, taxes, product information and integration acceptance are required before launch.']};
function policy(kind){const p=policies[kind];if(!p)return notFound();return `<section class="section-wrap article">${heading('THE SMALL PRINT',p[0],'Working policy preview · not final terms for a live store.')}<div class="policy-copy">${p.slice(1).map((x,i)=>`<section><span class="eyebrow">0${i+1}</span><p>${x}</p></section>`).join('')}</div>${link('Need a little help?','/contact','text-link')}</section>`;}
function settings(){return `<section class="section-wrap article">${heading('YOUR CHOICE','A little more control.<br><em>All yours.</em>','Choose whether you want optional communications. These settings are stored in this browser only in the preview.')}<form id="preferences-form" class="form-panel"><label class="check"><input type="checkbox" name="email"><span>Optional email updates</span></label><label class="check"><input type="checkbox" name="whatsapp"><span>Optional WhatsApp updates</span></label><label class="check"><input type="checkbox" name="analytics"><span>Optional marketing analytics exports (inactive in preview)</span></label><p class="micro">Necessary session and order records support the local application. No external analytics or messaging connection is active.</p><button class="button">Save my choices <span>✓</span></button></form></section>`;}
function searchPage(){const q=new URL(location.href).searchParams.get('q')||'';const match=state.catalog.filter(p=>(p.name+' '+p.ingredients+' '+format[p.id]).toLowerCase().includes(q.toLowerCase()));const report=/report|lot|test|proof/i.test(q);return `<section class="section-wrap">${heading('A LITTLE DISCOVERY','What are you<br><em>curious about?</em>')}<form id="page-search" class="inline-search"><label class="sr-only" for="page-query">Search products</label><input id="page-query" name="q" value="${escape(q)}" placeholder="Product or ingredient name"><button class="button">Search ↗</button></form><p>${match.length} product match${match.length===1?'':'es'} ${q?'for “'+escape(q)+'”':''}</p>${report?`<div class="note-panel">${link('Find your lot report','/reports','text-link')}</div>`:''}${match.length?grid(match):empty('Let’s try another question.','Try “creatine”, “iron”, “softgels” or “lot reports”.','Explore all seven','/shop')}</section>`;}

const opsTabs=[['overview','Overview'],['orders','Orders'],['inventory','Inventory & batches'],['products','Products & prices'],['cases','Support & safety'],['approvals','Approvals'],['audit','Audit history'],['analytics','Analytics'],['channels','Channels & integrations'],['flags','Feature flags']];
function opsLogin(){return `<section class="section-wrap">${heading('OPERATIONS / LOCAL PREVIEW','The detail behind<br><em>the everyday.</em>','Explore the operational workflows with explicit demo identities. Microsoft SSO and MFA are not connected.')}<div class="demo-identities">${[['admin-a','Admin A','Initiate changes, quarantine lots and manage orders.'],['admin-b','Admin B','A different person for approval demonstrations.'],['viewer','Viewer','Read-only, enforced on server endpoints.']].map(([id,t,d])=>`<article><span class="eyebrow">PREVIEW IDENTITY</span><h2>${t}</h2><p>${d}</p><button class="button" data-demo-login="${id}">Enter as ${t} ↗</button></article>`).join('')}</div><div class="note-panel">This is a localhost-only demonstration. Real organisational identity, account provisioning and production approval ownership remain required.</div></section>`;}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">No records yet.</td></tr>`}</tbody></table></div>`;}
function ops(tab='overview'){if(!['admin','viewer'].includes(state.user.role))return opsLogin();const o=state.ops;const viewer=state.user.role==='viewer';let content='';const orders=o.orders;const delivered=orders.filter(x=>x.state==='delivered');const captured=o.payments.filter(x=>x.status==='captured').reduce((n,x)=>n+x.amount,0);
  if(tab==='overview')content=`<div class="metric-grid">${[['Orders',orders.length],['Captured sample value',money(captured)],['Delivered',delivered.length],['Open cases',o.cases.filter(x=>x.state!=='resolved').length]].map(([l,v])=>`<article><span>${l}</span><strong>${v}</strong></article>`).join('')}</div><div class="ops-section"><h2>Ready for attention.</h2><div class="attention-grid"><a href="/ops/approvals"><strong>${o.approvals.filter(x=>x.state==='pending').length}</strong><span>Changes awaiting approval ↗</span></a><a href="/ops/inventory"><strong>${o.batches.filter(x=>x.state==='quarantined').length}</strong><span>Quarantined lots ↗</span></a><a href="/ops/cases"><strong>${o.cases.filter(x=>x.kind==='safety'&&x.state!=='resolved').length}</strong><span>Active safety cases ↗</span></a></div></div><div class="note-panel"><strong>Preview ledger, durable local records.</strong><p>External payment, courier, identity and Amazon connections are inactive. A successful preview action does not move money or dispatch a product.</p></div>`;
  else if(tab==='orders')content=table(['Order','State','Sample total','Provider','Action'],orders.map(x=>[x.id,badge(x.state),money(x.total),escape(x.provider||'Not assigned'),`${link('View','/orders/'+x.id,'small-link')}${['paid','shipped'].includes(x.state)?`<button class="small-button" data-ship="${x.id}" ${viewer?'disabled':''}>${x.state==='paid'?'Simulate shipment':'Mark delivered'}</button>`:''}${x.refund==='approval_pending'?`<button class="small-button" data-refund="${x.id}" ${viewer?'disabled':''}>Request refund approval</button>`:''}`]));
  else if(tab==='inventory')content=`<p>FEFO selects the earliest-expiring released lot. Reservations decrement available stock atomically. Quarantine immediately prevents new allocation and shipping.</p>${table(['Lot / product','Expiry','Available','Evidence / state','Actions'],o.batches.map(b=>[`${b.id}<small>${product(b.product)?.name||b.product}</small>`,date(b.expiry),b.available,`${badge(b.proof?'Sample proof present':'Proof missing')}${badge(b.state)}`,`<button class="small-button" data-quarantine="${b.id}" ${viewer||b.state==='quarantined'?'disabled':''}>Quarantine</button><button class="small-button" data-stock="${b.id}" ${viewer?'disabled':''}>Request stock addition</button>${b.state==='quarantined'?`<button class="small-button" data-release="${b.id}" ${viewer?'disabled':''}>Request release</button>`:''}`]))}`;
  else if(tab==='products')content=`<p>All listed prices are illustrative. Price and publication changes require a different Admin’s approval.</p>${table(['Product','Sample price','Publication','Content readiness','Actions'],state.catalog.map(p=>[p.name,money(p.price),badge(p.published?'Published preview':'Hidden'),badge('Approved rear label pending'),`<button class="small-button" data-price="${p.id}" ${viewer?'disabled':''}>Request price change</button><button class="small-button" data-publication="${p.id}" ${viewer?'disabled':''}>${p.published?'Request unpublish':'Request publish'}</button>`]))}`;
  else if(tab==='cases')content=`<p>Case IDs, ownership and state changes stay in the ledger. A safety case must be assessed; quarantine can be initiated immediately by an Admin.</p>${table(['Case','Type / state','Message','Order / SLA','Actions'],o.cases.map(c=>[c.id,`${badge(c.kind,c.kind==='safety'?'warning':'')}${badge(c.state)}`,escape(c.message),`${escape(c.order_id||'No order')}<small>${escape(c.sla)}</small>`,`${['investigating','escalated','resolved'].map(s=>`<button class="small-button" data-case-state="${s}" data-id="${c.id}" ${viewer?'disabled':''}>${s}</button>`).join('')}`]))}`;
  else if(tab==='approvals')content=`<p>No self-approval. Switch to the other preview Admin to approve a request. Real production identities must enforce the same separation.</p><div class="identity-tools">${['admin-a','admin-b','viewer'].map(id=>`<button class="small-button" data-demo-login="${id}">${id}</button>`).join('')}</div>${table(['Request','Change','Creator','State','Decision'],o.approvals.map(a=>[a.id,`${a.kind}: ${escape(a.target)}<small>${escape(JSON.stringify(a.payload))}</small>`,a.creator,badge(a.state),a.state==='pending'?`<button class="small-button" data-approval="${a.id}" data-decision="approve" ${viewer||a.creator===state.user.id?'disabled':''}>Approve</button><button class="small-button" data-approval="${a.id}" data-decision="reject" ${viewer||a.creator===state.user.id?'disabled':''}>Reject</button>`:escape(a.approver||'—')]))}`;
  else if(tab==='audit')content=`<p>Append-only application audit trail. Database access and production tamper resistance require deployment controls.</p>${table(['Time','Actor','Action','Record'],o.audit.slice(0,200).map(a=>[date(a.created),a.actor,a.action,a.target]))}`;
  else if(tab==='analytics')content=`<div class="metric-grid">${[['Preview delivered value',money(delivered.reduce((n,x)=>n+x.total,0))],['Sample delivery rate',orders.length?Math.round(delivered.length/orders.length*100)+'%':'—'],['Cases',o.cases.length],['Verified review submissions',o.reviews.length]].map(([l,v])=>`<article><span>${l}</span><strong>${v}</strong></article>`).join('')}</div><div class="note-panel"><strong>Delivered contribution: awaiting finance inputs.</strong><p>COGS, taxes, payment fees, billed shipping, returns and other attributable costs are not approved. Revenue is not presented as contribution.</p></div><h2>First-party events.</h2>${table(['Event','Count'],o.events.map(e=>[e.name,e.count]))}<p class="micro">No external analytics exports are active. Event records do not contain contact data or support narratives.</p>`;
  else if(tab==='channels')content=`<div class="integration-grid">${[['Razorpay','Not connected','Server signatures, webhooks and settlement reconciliation required.'],['Mobile OTP / email','Preview codes only','Provider credentials, rate limits and email fallback required.'],['Microsoft SSO + MFA','Not connected','Organisational tenant and real users required.'],['Vayuvega','Preview assignment only','Contract, serviceability, booking and reconciliation integration required.'],['Shipneer','Preview assignment only','Contract, serviceability, booking and reconciliation integration required.'],['Amazon FBA','Agency boundary pending','FBA-only scope; Amazon stock and bulk replenishment stay distinct from D2C.'],['WhatsApp / email support','Not connected','Business contacts, sender configuration and consented communication required.'],['Unit authenticity','Scope unresolved','Lot lookup is separate from a concealed unit code.']].map(([t,s,d])=>`<article><h2>${t}</h2>${badge(s)}<p>${d}</p></article>`).join('')}</div><div class="note-panel"><strong>Release readiness</strong><p>Keep independent D2C and Amazon acceptance checklists; the later direction requests a coordinated public launch. No channel is marked ready from this preview.</p></div>`;
  else if(tab==='flags')content=`<p>These provisional flags demonstrate governed configuration. Turning a flag on does not create an external integration or approve missing content.</p>${table(['Flag','Current state','Action'],Object.entries(o.flags).map(([k,v])=>[k,badge(v?'On':'Off'),`<button class="small-button" data-flag="${k}" data-value="${!v}" ${viewer?'disabled':''}>Request ${v?'disable':'enable'}</button>`]))}`;
  else return notFound();
  return `<div class="ops-layout"><aside class="ops-sidebar"><p class="eyebrow">BODY CAFÉ CO. / OPERATIONS</p><h2>The daily<br>detail.</h2><p>${escape(state.user.name)} ${badge(state.user.role)}</p><nav aria-label="Operations sections">${opsTabs.map(([id,l])=>`<a class="${id===tab?'active':''}" href="/ops${id==='overview'?'':'/'+id}">${l}<span>↗</span></a>`).join('')}</nav><button class="small-button" data-action="logout">Leave operations</button></aside><section class="ops-content"><div class="ops-heading"><div><p class="eyebrow">LOCAL PREVIEW / ${viewer?'READ-ONLY':'ADMIN'}</p><h1>${opsTabs.find(x=>x[0]===tab)[1]}</h1></div><button class="small-button" data-action="refresh">Refresh ↻</button></div>${content}</section></div>`;
}
function notFound(){return `<section class="section-wrap">${empty('A little off the path.','We couldn’t find this page. Let’s take you back.','Back to the collection','/shop')}</section>`;}

let renderVersion=0;
async function render(scroll=true){const version=++renderVersion;document.body.dataset.theme=state.theme==='b'?'b':'a';const path=location.pathname;try{
    let content;
    if(path.startsWith('/account')||path.startsWith('/orders/')||path.startsWith('/payment/'))state.account=await api('/account');
    if(path.startsWith('/ops')&&['admin','viewer'].includes(state.user.role))state.ops=await api('/admin');
    if(version!==renderVersion)return;
    if(path==='/')content=home();else if(path==='/shop')content=shop();else if(path.startsWith('/products/'))content=detail(product(path.split('/')[2]));else if(path.startsWith('/bundles'))content=bundles(path.split('/')[2]);else if(path==='/standards')content=standards();else if(path.startsWith('/learn'))content=state.flags.ingredient_library?learn(path.split('/')[2]):`<section class="section-wrap">${empty('A little reading, on pause.','The ingredient library is currently unpublished.','Explore the collection','/shop')}</section>`;else if(path==='/story')content=story();else if(path==='/reports')content=reports();else if(path==='/cart')content=cart();else if(path==='/checkout')content=checkout();else if(path.startsWith('/account'))content=account(path.split('/')[2]||'orders');else if(path.startsWith('/orders/'))content=orderDetail(state.account.orders.find(o=>o.id===path.split('/')[2]));else if(path.startsWith('/payment/'))content=payment(state.account.orders.find(o=>o.id===path.split('/')[2]));else if(path==='/help')content=help();else if(path==='/contact')content=contact();else if(path.startsWith('/policies/'))content=policy(path.split('/')[2]);else if(path==='/settings')content=settings();else if(path==='/search')content=searchPage();else if(path.startsWith('/ops'))content=ops(path.split('/')[2]||'overview');else content=notFound();
    $('#app').innerHTML=shell(content);document.title=(path==='/'?'Your everyday, with clarity':path.split('/').filter(Boolean).map(x=>x.replaceAll('-',' ')).join(' · '))+' — Body Café Co.';
    if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
    if(path==='/settings'){let pref={};try{pref=JSON.parse(localStorage.getItem('bcc-preferences')||'{}');}catch{}for(const k of ['email','whatsapp','analytics'])$(`#preferences-form [name=${k}]`).checked=!!pref[k];}
  }catch(e){$('#app').innerHTML=shell(`<section class="section-wrap">${empty('A little interruption.',escape(e.message),'Try the collection','/shop')}</section>`);}
}
function navigate(href){history.pushState({},'',href);render();}
async function refreshCatalog(){const c=await api('/catalog');state.catalog=c.products;state.bundles=c.bundles;state.flags=c.flags;}
function formError(form,error){const box=form.querySelector('.form-error');if(box)box.textContent=error.message;else toast(error.message);}
async function opsAction(action,data){await api('/admin/'+action,data);await refreshCatalog();await render(false);toast('Preview record updated.');}
document.addEventListener('click',async e=>{
  const button=e.target.closest('button');const anchor=e.target.closest('a');
  if(anchor&&anchor.origin===location.origin&&!anchor.getAttribute('href').startsWith('#')&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey){e.preventDefault();if($('#search-dialog').open)$('#search-dialog').close();navigate(anchor.href);return;}
  if(!button)return;
  try{
    if(button.dataset.themeChoice){state.theme=button.dataset.themeChoice;localStorage.setItem('bcc-theme',state.theme);const u=new URL(location.href);u.searchParams.set('theme',state.theme);history.replaceState({},'',u);await render(false);}
    else if(button.dataset.add)add(button.dataset.add);
    else if(button.dataset.bundle){const bundle=state.bundles.find(b=>b.id===button.dataset.bundle);if(bundle.items.some(id=>{const p=product(id);return !p.published||p.stock<(state.cart.find(i=>i.id===id)?.quantity||0)+1||(state.cart.find(i=>i.id===id)?.quantity||0)>=10;}))return toast('One of these products is unavailable.');bundle.items.forEach(id=>add(id));}
    else if(button.dataset.quantity){const item=state.cart.find(i=>i.id===button.dataset.quantity);item.quantity+=Number(button.dataset.change);if(item.quantity>10){item.quantity=10;return toast('Maximum preview quantity is 10.');}state.cart=state.cart.filter(i=>i.quantity>0);saveCart();render(false);}
    else if(button.dataset.remove){state.cart=state.cart.filter(i=>i.id!==button.dataset.remove);saveCart();render(false);}
    else if(button.dataset.reportProduct){const pid=button.dataset.reportProduct;$('#report-product').value=pid;document.querySelectorAll('[data-report-product]').forEach(b=>{const selected=b.dataset.reportProduct===pid;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});$('#report-result').replaceChildren();$('#sample-lot').textContent='DEMO-'+String(state.catalog.findIndex(p=>p.id===pid)+1).padStart(2,'0')+'-01';}
    else if(button.dataset.sampleLot){$('#lot').value=button.dataset.sampleLot;$('#report-form').requestSubmit();}
    else if(button.dataset.demoLogin){await api('/demo/login',{identity:button.dataset.demoLogin});await session();navigate(location.pathname.startsWith('/ops')?location.pathname:'/ops');toast('Local preview identity active.');}
    else if(button.dataset.pay){button.disabled=true;const r=await api('/orders/'+button.dataset.id+'/pay',{outcome:button.dataset.pay});if(r.state==='paid'){state.cart=[];saveCart();await refreshCatalog();navigate('/orders/'+button.dataset.id);toast('Preview payment succeeded. No money moved.');}else{$('#payment-result').textContent=r.message;button.disabled=false;}}
    else if(button.dataset.cancel){await api('/orders/'+button.dataset.cancel+'/cancel',{});await refreshCatalog();await render(false);toast('Preview order cancelled. Paid refunds await approval.');}
    else if(button.dataset.reorder){const o=state.account.orders.find(o=>o.id===button.dataset.reorder);o.items.forEach(i=>add(i.id,i.quantity));navigate('/cart');}
    else if(button.dataset.ship)await opsAction('ship',{id:button.dataset.ship});
    else if(button.dataset.quarantine){const reason=prompt('Reason for quarantining this preview lot:');if(reason)await opsAction('quarantine',{batch:button.dataset.quarantine,reason});}
    else if(button.dataset.stock){const raw=prompt('Preview units to add (requires another Admin’s approval):','10');if(raw!==null&&raw.trim()&&Number.isInteger(Number(raw)))await opsAction('request',{kind:'stock',target:button.dataset.stock,value:Number(raw),reason:'Preview stock addition'});}
    else if(button.dataset.price){const raw=prompt('New sample price in whole rupees (requires another Admin):',String(product(button.dataset.price).price));if(raw!==null&&raw.trim()&&Number.isInteger(Number(raw)))await opsAction('request',{kind:'price',target:button.dataset.price,value:Number(raw),reason:'Preview price change'});}
    else if(button.dataset.publication)await opsAction('request',{kind:'publication',target:button.dataset.publication,value:!product(button.dataset.publication).published});
    else if(button.dataset.release)await opsAction('request',{kind:'release',target:button.dataset.release,value:true});
    else if(button.dataset.refund)await opsAction('request',{kind:'refund',target:button.dataset.refund});
    else if(button.dataset.approval)await opsAction('approve',{id:button.dataset.approval,decision:button.dataset.decision});
    else if(button.dataset.caseState)await opsAction('case',{id:button.dataset.id,state:button.dataset.caseState});
    else if(button.dataset.flag)await opsAction('request',{kind:'flags',target:button.dataset.flag,value:button.dataset.value==='true'});
    else if(button.dataset.action==='menu'){const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;button.setAttribute('aria-expanded',String(open));button.textContent=open?'Close −':'Menu ＋';}
    else if(button.dataset.action==='search')$('#search-dialog').showModal();
    else if(button.dataset.action==='close-search')$('#search-dialog').close();
    else if(button.dataset.action==='logout'){await api('/logout',{});await session();navigate('/account');}
    else if(button.dataset.action==='refresh'){await refreshCatalog();await render(false);}
    else if(button.dataset.action==='add-product')add(button.dataset.id,Number($('#product-quantity').value));
    else if(button.dataset.action==='discount'){const code=$('#discount-code').value.trim().toUpperCase();if(code&&code!=='PREVIEW10')return toast('Use PREVIEW10 for a sample discount.');const d=code?Math.round(total()*.1):0,shipping=total()-d>=1499?0:75;$('#checkout-discount').textContent='−'+money(d);$('#checkout-shipping').textContent=shipping?money(shipping):'Free';$('#checkout-total').textContent=money(total()-d+shipping);}
  }catch(error){toast(error.message);button.disabled=false;}
});
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;const data=Object.fromEntries(new FormData(form));const error=form.querySelector('.form-error');if(error)error.textContent='';try{
    if(['search-form','page-search'].includes(form.id)){if($('#search-dialog').open)$('#search-dialog').close();navigate('/search?q='+encodeURIComponent(data.q||''));}
    else if(form.id==='pincode-form')$('#pincode-result').textContent='Sample estimate: 3–7 business days. Live serviceability and dates require courier setup.';
    else if(form.id==='checkout-form'){const o=await api('/orders',{...data,contact:Object.fromEntries(['name','mobile','email','pincode','address','city','state'].map(k=>[k,data[k]||''])),items:state.cart,adult:form.elements.adult.checked,email_consent:form.elements.email_consent.checked,whatsapp_consent:form.elements.whatsapp_consent.checked});navigate('/payment/'+o.id);}
    else if(form.id==='report-form'){const result=$('#report-result');result.innerHTML='<p>Looking up the sample record…</p>';event('report_lookup');try{const r=await api('/reports?product='+encodeURIComponent(data.product)+'&lot='+encodeURIComponent(data.lot));const t={sample_match:['A sample match.','This illustrative lot belongs to the selected product. No laboratory report is attached.'],not_found:['No matching lot.','Check the number and product, then try again. You can contact support if it still doesn’t match.'],unpublished:['Report not published.','The sample record is not ready to view. This is not a claim that a test passed.'],withdrawn:['This sample lot is withdrawn.','In the live experience, reviewed safety instructions and a direct support route would appear here.']}[r.state];result.innerHTML=`<div class="report-result ${r.state==='withdrawn'?'warning':''}"><p class="eyebrow">ILLUSTRATIVE RECORD / ${escape(r.lot)}</p><h2>${t[0]}</h2><p>${t[1]}</p><p class="micro">Report version: preview only. Source document: not supplied. Individual unit authenticity: not verified.</p><a class="text-link" href="/contact">Ask about this lot ↗</a></div>`;}catch(error){result.innerHTML=`<div class="report-result warning"><h2>A little interruption.</h2><p>${escape(error.message)}</p><button type="submit" class="small-button">Try again</button></div>`;}}
    else if(form.id==='otp-form'){state.otp={mobile:data.mobile,...await api('/auth/otp',data)};$('#otp-result').innerHTML=`<div class="preview-code"><strong>Local preview code: ${state.otp.preview_code}</strong><p>No SMS was sent. Expires in five minutes.</p><label for="verify-code">Enter preview code</label><input id="verify-code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}"><button type="button" class="button full" id="verify-button">Verify local code →</button></div>`;$('#verify-button').onclick=async()=>{try{await api('/auth/verify',{mobile:state.otp.mobile,code:$('#verify-code').value});await session();await render(false);toast('Preview mobile verified. Matching guest orders claimed.');}catch(err){toast(err.message);}};}
    else if(form.id==='case-form'){const c=await api('/cases',data);$('#case-result').innerHTML=`<div class="report-result"><p class="eyebrow">PREVIEW CASE CREATED</p><h2>${c.id}</h2><p>Your case is saved locally. ${c.kind==='safety'?'It is marked for priority safety review.':''}</p><a class="text-link" href="/account/cases">Follow your case ↗</a></div>`;form.reset();}
    else if(form.id==='address-form'){await api('/addresses',data);await render(false);toast('Preview address saved.');}
    else if(form.id==='review-form'){await api('/reviews',{...data,rating:Number(data.rating)});toast('Review submitted for preview moderation.');form.reset();}
    else if(form.id==='preferences-form'){const pref=Object.fromEntries(['email','whatsapp','analytics'].map(k=>[k,form.elements[k].checked]));localStorage.setItem('bcc-preferences',JSON.stringify(pref));event('consent_updated');toast('Your browser preview choices are saved.');}
  }catch(err){formError(form,err);}finally{if(button)button.disabled=false;}
});
document.addEventListener('change',e=>{if(e.target.id==='report-product'){document.querySelector(`[data-report-product="${e.target.value}"]`)?.click();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#mobile-nav')&&!$('#mobile-nav').hidden){$('#mobile-nav').hidden=true;const b=$('[data-action=menu]');b.setAttribute('aria-expanded','false');b.textContent='Menu ＋';b.focus();}});
window.addEventListener('popstate',()=>render());
setInterval(()=>{document.querySelectorAll('[data-expires]').forEach(x=>{const seconds=Math.max(0,Number(x.dataset.expires)-Math.floor(Date.now()/1000));x.textContent=seconds?`Reservation: ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')} remaining`:'Reservation expired. Start a new checkout.';});},1000);
try{state.theme=state.theme==='b'?'b':'a';localStorage.setItem('bcc-theme',state.theme);await session();await refreshCatalog();state.cart=state.cart.filter(i=>product(i.id));saveCart();await render(false);}catch(e){$('#app').innerHTML=`<div class="boot">A little interruption.<p>${escape(e.message)}</p><p>Start the local Python preview server, then reload.</p></div>`;}
